-- Rollback-only exact recovery sources/effects. Provider/password facts are synthetic fixtures.
begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api,cuevo_worker;
set local search_path=extensions,pg_catalog;select no_plan();select internal.configure_worker_dispatch(false,null,null,false);select set_config('app.runtime_env','local',true);
select ok(to_regprocedure('internal.create_school_account_recovery(uuid,jsonb,text,text,text)')is not null,'one exact administrator recovery source exists');
select ok(to_regprocedure('internal.authorize_school_account_recovery(uuid,text,text,text,text)')is not null and to_regprocedure('internal.complete_school_account_recovery(uuid,text,text,text)')is not null,'recovery has separate recipient authorization/password observation');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join pg_roles role where n.nspname='internal'and c.relname in('school_account_recovery_authorizations','school_account_recovery_completions')and role.rolname in('anon','authenticated','service_role','cuevo_api','cuevo_worker')and(has_table_privilege(role.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_any_column_privilege(role.oid,c.oid,'SELECT,INSERT,UPDATE,REFERENCES'))),'recovery password markers/receipts have no raw runtime grants');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='internal'and c.relname in('school_account_recovery_authorizations','school_account_recovery_completions')and(not c.relrowsecurity or not c.relforcerowsecurity)),'recovery receipt tables force RLS');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join pg_roles role where n.nspname='internal'and p.proname in('require_school_account_source_authority','school_account_effect_ready','lock_school_account_recovery_recipient')and role.rolname in('anon','authenticated','service_role','cuevo_api','cuevo_worker')and has_function_privilege(role.oid,p.oid,'EXECUTE')),'shared authority/effect helpers remain owner-only');
select ok(not has_function_privilege('cuevo_worker','internal.create_school_account_recovery(uuid,jsonb,text,text,text)','EXECUTE')and not has_function_privilege('authenticated','internal.authorize_school_account_recovery(uuid,text,text,text,text)','EXECUTE')and not has_function_privilege('service_role','internal.complete_school_account_recovery(uuid,text,text,text)','EXECUTE'),'worker and Data API cannot recover an account');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))permission where n.nspname='internal'and p.proname in('create_school_account_recovery','authorize_school_account_recovery','complete_school_account_recovery','require_school_account_source_authority','school_account_effect_ready','lock_school_account_recovery_recipient')and permission.grantee=0 and permission.privilege_type='EXECUTE'),'PUBLIC receives no recovery execution');
select is((select count(*)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='internal'and c.relname in('school_account_effect_leases','school_account_effect_attempts','school_account_effect_receipts','school_account_token_digests','school_account_effect_results')),5::bigint,'recovery reuses exactly the existing five effect/token tables');
create temporary table recovery_fixture(kind text primary key,id uuid,context jsonb,digest text,receipt jsonb);
create temporary table recovery_baseline(kind text primary key,snapshot jsonb);grant select,insert,update on recovery_fixture,recovery_baseline to cuevo_api,cuevo_worker;
select internal.configure_local_school_account_runtime(true,(select oid from pg_catalog.pg_database where datname=current_database()),'LOCAL_CUEVO','20000000-0000-4000-8000-000000000001','Explicit rollback recovery source',(select revision from internal.school_account_runtime_control where singleton),true);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into recovery_baseline select 'recipient',to_jsonb(m)from app.memberships m where m.school_id='10000000-0000-4000-8000-000000000001'and m.actor_id='20000000-0000-4000-8000-000000000012';
insert into auth.sessions(id,user_id,created_at,updated_at,not_after)values('20100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012',clock_timestamp(),clock_timestamp(),clock_timestamp()+interval'1 day');
set local role cuevo_api;
select throws_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000133','{"expectedMembershipRevision":1,"reason":"Foreign denied","confirmRecovery":true}','recovery-foreign',repeat('a',64),'recovery-test')$$,'42501',null,'foreign-school existing account cannot receive local recovery');
select throws_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012','{"expectedMembershipRevision":1,"reason":"Unconfirmed","confirmRecovery":false}','recovery-unconfirmed',repeat('a',64),'recovery-test')$$,'22023',null,'recovery requires explicit human approval');
select throws_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012','{"expectedMembershipRevision":999,"reason":"Stale","confirmRecovery":true}','recovery-stale',repeat('a',64),'recovery-test')$$,'42501',null,'recovery pins current recipient member revision');
select throws_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012','{"expectedMembershipRevision":1,"reason":"Extra fields","confirmRecovery":true,"email":"foreign@example.test"}','recovery-extra',repeat('a',64),'recovery-test')$$,'22023',null,'caller cannot redirect recovery email');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012','{"expectedMembershipRevision":1,"reason":"No administrator","confirmRecovery":true}','recovery-teacher',repeat('a',64),'recovery-test')$$,'42501',null,'teacher cannot authorize recovery for a school account');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
insert into recovery_fixture(kind,id)select 'primary',(internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012',jsonb_build_object('expectedMembershipRevision',1,'reason','Reviewed existing account recovery','confirmRecovery',true),'recovery-primary',repeat('a',64),'recovery-test')->>'id')::uuid;
select is(internal.read_school_account_invitations(25,null)->'items'->0->>'purpose','recovery','administrator rows disclose recovery purpose without inviting another membership');
update recovery_fixture set context=internal.claim_school_account_effect(id)where kind='primary';
select throws_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012','{"expectedMembershipRevision":1,"reason":"Duplicate recovery","confirmRecovery":true}','recovery-duplicate',repeat('b',64),'recovery-test')$$,'22023',null,'another request cannot regenerate current recovery effects');
select is((select context->>'purpose'from recovery_fixture where kind='primary'),'recovery','shared exact effect context declares recovery purpose');
select is((select context->>'userId'from recovery_fixture where kind='primary'),'20000000-0000-4000-8000-000000000012','recovery never allocates a new provider UUID');
select ok(internal.begin_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'CREATE','20100000-0000-4000-8000-000000000002',null),'recovery reserves exact read-only identity reconciliation')from recovery_fixture where kind='primary';
select throws_ok($$select internal.finish_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'CREATE','20100000-0000-4000-8000-000000000002','{"state":"CONFIRMED","code":"IDENTITY_CONFIRMED","emailConfirmed":null}')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'recovery requires confirmed email rather than nullable invite evidence');
select ok(internal.finish_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'CREATE','20100000-0000-4000-8000-000000000002','{"state":"CONFIRMED","code":"IDENTITY_CONFIRMED","emailConfirmed":true}'),'recovery identity receipt agrees with current confirmed Auth UUID')from recovery_fixture where kind='primary';
update recovery_fixture set digest=repeat('c',64)where kind='primary';
select ok(internal.begin_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'LINK','20100000-0000-4000-8000-000000000003',digest),'recovery link uses same durable digest ledger')from recovery_fixture where kind='primary';
select ok(internal.finish_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'LINK','20100000-0000-4000-8000-000000000003','{"state":"CONFIRMED","code":"LINK_GENERATED"}'),'recovery link receipt is minimized')from recovery_fixture where kind='primary';
select ok(internal.begin_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'DELIVERY','20100000-0000-4000-8000-000000000004',null),'recovery delivery reserves its own original effect')from recovery_fixture where kind='primary';
select ok(internal.finish_school_account_effect_step((context->>'eventId')::uuid,(context->>'leaseToken')::uuid,'DELIVERY','20100000-0000-4000-8000-000000000004','{"state":"CONFIRMED","code":"DELIVERY_ACCEPTED"}'),'recovery capture acceptance is distinct from password change')from recovery_fixture where kind='primary';
update recovery_fixture set receipt=internal.finish_school_account_effect((context->>'eventId')::uuid,(context->>'leaseToken')::uuid)where kind='primary';
select is((select receipt->>'status'from recovery_fixture where kind='primary'),'AWAITING_CLAIM','shared effect finish awaits deliberate own-account continuation');
reset role;
select is((select purpose from internal.school_account_token_digests where request_id=(select id from recovery_fixture where kind='primary')),'recovery','digest is pinned to recovery purpose');
select ok(not internal.school_account_admission_effect_ready(r,t),'recovery token cannot create school membership through invitation helper')from internal.school_account_requests r join internal.school_account_token_digests t on t.request_id=r.id where r.id=(select id from recovery_fixture where kind='primary');
select ok(internal.school_account_effect_ready(r,t),'shared canonical effect helper verifies recovery chain')from internal.school_account_requests r join internal.school_account_token_digests t on t.request_id=r.id where r.id=(select id from recovery_fixture where kind='primary');
select throws_ok($$update internal.school_account_requests set purpose='invite',current_revision=current_revision+1 where id=(select id from pg_temp.recovery_fixture where kind='primary')$$,'55000',null,'recovery purpose cannot mutate into invitation authority');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select set_config('app.school_id','',true);select set_config('app.session_id','20100000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.claim_school_account_invitation(id,digest,'recovery-as-invite',repeat('b',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'recovery never enters membership-claim function');
select throws_ok($$select internal.authorize_school_account_recovery(id,repeat('f',64),'recovery-auth',repeat('b',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'wrong app digest cannot authorize password recovery');
select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.authorize_school_account_recovery(id,digest,'recovery-auth',repeat('b',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'recipient cannot choose school for recovery authority');
select set_config('app.school_id','',true);
select set_config('app.session_id','',true);
select throws_ok($$select internal.authorize_school_account_recovery(id,digest,'recovery-auth',repeat('b',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'missing current session cannot authorize password changes');
select set_config('app.session_id','20100000-0000-4000-8000-000000000001',true);
update recovery_fixture set receipt=internal.authorize_school_account_recovery(id,digest,'recovery-auth',repeat('b',64),'recovery-test')where kind='primary';
select is((select receipt->>'status'from recovery_fixture where kind='primary'),'AUTHORIZED','verified current recipient authorizes exact recovery without changing password');
select set_config('app.school_id','',true);
select is(internal.authorize_school_account_recovery(id,digest,'recovery-auth',repeat('b',64),'recovery-test'),receipt,'same original authorization key reconciles before password changes')from recovery_fixture where kind='primary';
select set_config('app.school_id','',true);
select throws_ok($$select internal.authorize_school_account_recovery(id,digest,'recovery-other',repeat('b',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'22023',null,'single-use authorization cannot use another key');
select throws_ok($$select internal.complete_school_account_recovery(id,'recovery-complete',repeat('d',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'P0002',null,'only fully authorized unchanged provider password permits an explicit new save');
reset role;
savepoint recovery_approver_authority;
update app.memberships set status='suspended'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000001';
set local role cuevo_api;select set_config('app.school_id','',true);
select throws_ok($$select internal.complete_school_account_recovery(id,'recovery-complete',repeat('d',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'lost approving administrator denies before unchanged-password permission');
reset role;rollback to savepoint recovery_approver_authority;release savepoint recovery_approver_authority;
savepoint recovery_current_authority;
update app.memberships set status='suspended'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;select set_config('app.school_id','',true);
select throws_ok($$select internal.complete_school_account_recovery(id,'recovery-complete',repeat('d',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'lost recipient authority never returns unchanged-password save permission');
reset role;
rollback to savepoint recovery_current_authority;
release savepoint recovery_current_authority;
update auth.users set encrypted_password=encrypted_password||':synthetic-changed-password-fixture'where id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;select set_config('app.school_id','',true);
select throws_ok($$select internal.authorize_school_account_recovery(id,digest,'recovery-auth',repeat('b',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'22023',null,'changed password cannot replay prechange authorization as unchanged');
update recovery_fixture set receipt=internal.complete_school_account_recovery(id,'recovery-complete',repeat('d',64),'recovery-test')where kind='primary';
select is((select receipt->>'status'from recovery_fixture where kind='primary'),'COMPLETED','completion observes changed provider hash without password or access writes');
select set_config('app.school_id','',true);
select is(internal.complete_school_account_recovery(id,'recovery-complete',repeat('d',64),'recovery-replay'),receipt,'current original completion key reconciles exact changed password observation')from recovery_fixture where kind='primary';
select set_config('app.school_id','',true);
select throws_ok($$select internal.complete_school_account_recovery(id,'other-complete',repeat('d',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'22023',null,'another completion key cannot replace immutable recovery');
reset role;
select is(to_jsonb(m),(select snapshot from recovery_baseline where kind='recipient'),'password recovery leaves role/status/member revision/windows unchanged')from app.memberships m where m.school_id='10000000-0000-4000-8000-000000000001'and m.actor_id='20000000-0000-4000-8000-000000000012';
select ok(not exists(select 1 from internal.audit_events audit where audit.entity_id=(select id from recovery_fixture where kind='primary')and audit.metadata::text~'password|digest|token|email'),'canonical recovery audit excludes credentials and private password marker');
select is((select count(*)from internal.outbox_events event where event.entity_id=(select id from recovery_fixture where kind='primary')and event.type='school.account.recovery_authorized'),1::bigint,'authorization commits one idempotent deterministic observation event');
select is((select count(*)from internal.outbox_events event where event.entity_id=(select id from recovery_fixture where kind='primary')and event.type='school.account.recovery_completed'),1::bigint,'password observation commits one idempotent deterministic completion event');
select ok(not exists(select 1 from internal.outbox_events event where event.entity_id=(select id from recovery_fixture where kind='primary')and event.type in('school.account.recovery_authorized','school.account.recovery_completed')and event.metadata is distinct from'{"requestRevision":1}'::jsonb),'recovery observation events contain only exact request revision');
insert into recovery_fixture(kind,id)select event.type,event.id from internal.outbox_events event where event.entity_id=(select id from recovery_fixture where kind='primary')and event.type in('school.account.recovery_authorized','school.account.recovery_completed');
update internal.outbox_events event set state='PROCESSING',attempt_count=1,lease_token=event.id,lease_until=clock_timestamp()+interval'1 minute'where event.id in(select id from recovery_fixture where kind in('school.account.recovery_authorized','school.account.recovery_completed'));
savepoint recovery_event_forgery;
update internal.outbox_events event set metadata='{"requestRevision":1,"passwordChanged":true}'where event.id=(select id from recovery_fixture where kind='school.account.recovery_completed');
set local role cuevo_worker;
select throws_ok($$select internal.process_learner_event(id,id)from pg_temp.recovery_fixture where kind='school.account.recovery_completed'$$,'22023',null,'forged completion metadata cannot authorize a worker observation');
reset role;rollback to savepoint recovery_event_forgery;release savepoint recovery_event_forgery;
set local role cuevo_worker;
select is(internal.process_learner_event(id,id),'{"status":"ACKNOWLEDGED"}'::jsonb,'worker acknowledges only the exact immutable recovery observation')from recovery_fixture where kind in('school.account.recovery_authorized','school.account.recovery_completed');
reset role;
select is((select count(*)from internal.outbox_events event where event.id in(select id from recovery_fixture where kind in('school.account.recovery_authorized','school.account.recovery_completed'))and event.state='COMPLETED'),2::bigint,'both recovery observations complete through existing worker authority');
select ok(not has_function_privilege('cuevo_api','internal.process_before_school_account_recovery_events(uuid,uuid)','EXECUTE')and not has_function_privilege('cuevo_worker','internal.process_before_school_account_recovery_events(uuid,uuid)','EXECUTE'),'new composed prior processor cannot bypass recovery ownership');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
set local role cuevo_api;
select lives_ok($$select internal.create_school_account_recovery('20000000-0000-4000-8000-000000000012','{"expectedMembershipRevision":1,"reason":"Later forgotten password after completed recovery","confirmRecovery":true}','later-recovery',repeat('e',64),'later-recovery-test')$$,'a later intentional recovery can create a new source after completed original recovery');
reset role;
select is((select count(*)from internal.school_account_requests source where source.purpose='recovery'and source.provider_user_id='20000000-0000-4000-8000-000000000012'and(source.id=(select id from recovery_fixture where kind='primary')or source.id=(select(canonical.response->>'id')::uuid from internal.idempotency_keys canonical where canonical.school_id='10000000-0000-4000-8000-000000000001'and canonical.actor_id='20000000-0000-4000-8000-000000000001'and canonical.key='later-recovery'and canonical.command='school.account.recovery.request'and canonical.state='COMPLETED'))),2::bigint,'later approved recovery retains both exact owned immutable sources without counting other valid recovery history');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select set_config('app.school_id','',true);
select throws_ok($$update internal.school_account_recovery_authorizations set password_digest=repeat('f',64)where request_id=(select id from pg_temp.recovery_fixture where kind='primary')$$,'55000',null,'original authorization/password marker is immutable');
select throws_ok($$delete from internal.school_account_recovery_completions where request_id=(select id from pg_temp.recovery_fixture where kind='primary')$$,'55000',null,'completion evidence is immutable');
update auth.sessions set not_after=clock_timestamp()-interval'1 second'where id='20100000-0000-4000-8000-000000000001';
set local role cuevo_api;select set_config('app.school_id','',true);
select throws_ok($$select internal.complete_school_account_recovery(id,'recovery-complete',repeat('d',64),'recovery-test')from pg_temp.recovery_fixture where kind='primary'$$,'42501',null,'expired prior session cannot replay recovery completion');
select throws_ok($$select password_digest from internal.school_account_recovery_authorizations$$,'42501',null,'API cannot retrieve private password comparison marker');
reset role;select*from finish();rollback;
